package com.metabuild.modules.admin.messages.persistence;
import com.metabuild.modules.admin.messages.application.InboxOutboxSignal;import java.time.*;import java.util.*;import org.jooq.*;import org.jooq.impl.DSL;
public final class InboxPublishOutboxWorker {private final DSLContext db;private final InboxOutboxSignal signal;private final String workerId=UUID.randomUUID().toString();public InboxPublishOutboxWorker(DSLContext db,InboxOutboxSignal signal){this.db=db;this.signal=signal;}public int drain(){signal.consume();var claimed=db.fetch("with picked as (select id from mb_inbox_publish_outbox where ((status in ('PENDING','FAILED') and next_attempt_at<=current_timestamp) or (status='PROCESSING' and lease_until<current_timestamp)) order by created_at for update skip locked limit 100) update mb_inbox_publish_outbox o set status='PROCESSING',worker_id=?,lease_until=current_timestamp+interval '30 seconds',attempts=attempts+1 from picked where o.id=picked.id returning o.*",workerId);for(var row:claimed)process(row);return claimed.size();}private void process(org.jooq.Record row){UUID id=row.get("id",UUID.class);try{db.transaction(configuration->{DSLContext tx=DSL.using(configuration);tx.execute("insert into mb_inbox_message(id,recipient_user_id,idempotency_key,category,title,sender,body,link,approval_status) values(?,?,?,?,?,'System',?,?,?) on conflict(recipient_user_id,idempotency_key) do nothing",id,row.get("recipient_user_id",UUID.class),row.get("idempotency_key",String.class),row.get("category",String.class),row.get("title",String.class),row.get("body",String.class),row.get("link",String.class),"approval".equals(row.get("category",String.class))?"pending":null);tx.execute("update mb_inbox_publish_outbox set status='DONE',worker_id=null,lease_until=null,processed_at=current_timestamp,last_error=null where id=? and worker_id=?",id,workerId);});}catch(RuntimeException failure){String error=failure.getMessage();db.execute("update mb_inbox_publish_outbox set status='FAILED',worker_id=null,lease_until=null,next_attempt_at=current_timestamp+least(interval '5 minutes',interval '1 second'*power(2,least(attempts,8))),last_error=? where id=? and worker_id=?",error==null?failure.getClass().getSimpleName():error.substring(0,Math.min(error.length(),2000)),id,workerId);}}
}
